import { useEffect, useRef, useState } from "react";
import { X } from "lucide-react";
import { Terminal as XTerm } from "xterm";
import { FitAddon } from "xterm-addon-fit";
import "xterm/css/xterm.css";
// @ts-ignore wailsjs bindings are generated by wails build
import { WindowRole } from "../../wailsjs/go/controllers/WindowInfo";
// @ts-ignore wailsjs bindings are generated by wails build
import { WindowClose } from "../../wailsjs/runtime";

// DetachedTerminal is the whole UI of a satellite `--terminal-window`
// process: one xterm bound to a PTY that lives in the main process. All
// traffic flows through the loopback owner endpoint with the bearer token
// this process was spawned with; no Wails bindings beyond the role probe
// and window close are used.

type Role = { role: string; ptyId?: string; ownerUrl?: string; token?: string };

type PollResult = {
  result?: { chunks?: { seq: number; data: string }[]; exited?: boolean };
  error?: string;
};

export default function DetachedTerminal() {
  const containerRef = useRef<HTMLDivElement>(null);
  const [exited, setExited] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    let cancelled = false;
    let poll: ReturnType<typeof setTimeout> | null = null;
    let since = 0;
    let term: XTerm | null = null;
    let fit: FitAddon | null = null;
    let owner = { url: "", token: "", ptyId: "" };

    const call = async (method: string, payload: Record<string, unknown>) => {
      const resp = await fetch(owner.url + "/call", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + owner.token,
        },
        body: JSON.stringify({ method, source: "terminal-window", payload }),
      });
      return (await resp.json()) as PollResult;
    };

    const pump = async () => {
      if (cancelled) return;
      try {
        const reply = await call("term_poll", { ptyId: owner.ptyId, since });
        if (cancelled) return;
        if (reply.error) {
          setError(reply.error);
          return;
        }
        const chunks = reply.result?.chunks ?? [];
        for (const chunk of chunks) {
          term?.write(chunk.data);
          since = Math.max(since, chunk.seq);
        }
        if (reply.result?.exited) {
          term?.write("\r\n\x1b[90m[process exited]\x1b[0m\r\n");
          setExited(true);
          return; // stop polling; the window stays for scrollback
        }
      } catch {
        setError("main window unreachable");
        return;
      }
      poll = setTimeout(pump, 80);
    };

    (async () => {
      try {
        const role = (await WindowRole()) as Role;
        if (cancelled || role.role !== "detached" || !role.ptyId || !role.ownerUrl || !role.token) {
          setError("this window lost its terminal binding");
          return;
        }
        owner = { url: role.ownerUrl, token: role.token, ptyId: role.ptyId };

        term = new XTerm({
          cursorBlink: true,
          cursorStyle: "block",
          fontSize: 13,
          fontFamily: "JetBrains Mono, Menlo, monospace",
          scrollback: 5000,
          theme: {
            background: "#171717",
            foreground: "#e4e6ff",
            cursor: "#7c5cff",
            selectionBackground: "#3d3d6b",
          },
        });
        fit = new FitAddon();
        term.loadAddon(fit);
        if (containerRef.current) term.open(containerRef.current);
        try {
          fit?.fit();
        } catch {
          /* not laid out yet */
        }

        term.onData((data) => {
          void call("term_write", { ptyId: owner.ptyId, data }).catch(() => {
            /* main process gone */
          });
        });

        const observer = new ResizeObserver(() => {
          try {
            fit?.fit();
            if (term && term.cols > 0 && term.rows > 0) {
              void call("term_resize", {
                ptyId: owner.ptyId, cols: term.cols, rows: term.rows,
              }).catch(() => { /* dead */ });
            }
          } catch {
            /* not laid out */
          }
        });
        if (containerRef.current) observer.observe(containerRef.current);

        void pump();
      } catch (err) {
        setError(String(err));
      }
    })();

    return () => {
      cancelled = true;
      if (poll) clearTimeout(poll);
      term?.dispose();
    };
  }, []);

  return (
    <div className="flex h-screen w-screen flex-col bg-[#171717]">
      <div
        data-titlebar
        style={{ "--wails-draggable": "drag" } as React.CSSProperties}
        className="flex h-8 shrink-0 items-center justify-end gap-1 px-2 select-none"
      >
        <span className="mr-auto text-[10px] text-white/30">kitodock · detached</span>
        <button
          type="button"
          onClick={() => WindowClose()}
          className="rounded p-1 text-white/50 hover:bg-white/10 hover:text-white"
        >
          <X className="h-3 w-3" />
        </button>
      </div>
      <div ref={containerRef} className="min-h-0 flex-1 overflow-hidden px-1 pb-1" />
      {exited && (
        <p className="px-3 pb-2 text-[10px] text-white/40">
          [process exited] — close this window; the pane can be reattached from the main window
        </p>
      )}
      {error && <p className="px-3 pb-2 text-[10px] text-red-300">{error}</p>}
    </div>
  );
}
